/**
 * @private
 */
export class TextSearchResult {
    constructor(owner) {
        this.startIn = undefined;
        this.endIn = undefined;
        this.owner = owner;
        this.documentHelper = this.owner.documentHelper;
    }
    get start() {
        return this.startIn;
    }
    set start(value) {
        this.startIn = value;
    }
    get end() {
        return this.endIn;
    }
    set end(value) {
        this.endIn = value;
    }
    get text() {
        return this.documentHelper.selection.getTextInternal(this.start, this.end, false);
    }
    destroy() {
        this.start = undefined;
        this.end = undefined;
    }
}
